/**
 * General help information for how to navigation a simulation with a keyboard. In general, this file supports a fair
 * number of options, like displaying group content, or shortcuts for checkbox interaction. The algorithm this type
 * implements set all the optional potential rows as null, and then fills them in if the options is provided. Then at the
 * end anything that is null is filtered out.
 *
 * @author Jesse Greenberg (PhET Interactive Simulations)
 * @author Michael Kauzmann (PhET Interactive Simulations)
 */
import { string_scenery_phet_keyboardHelpDialog_moveToNextItemOrGroup_StringProperty } from '../../strings/keyboardHelpDialog/moveToNextItemOrGroup.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_tabGroupDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/tabGroupDescription.js';
import { string_scenery_phet_keyboardHelpDialog_moveToPreviousItemOrGroup_StringProperty } from '../../strings/keyboardHelpDialog/moveToPreviousItemOrGroup.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_shiftTabGroupDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/shiftTabGroupDescription.js';
import { string_scenery_phet_keyboardHelpDialog_moveBetweenItemsInAGroup_StringProperty } from '../../strings/keyboardHelpDialog/moveBetweenItemsInAGroup.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_groupNavigationDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/groupNavigationDescription.js';
import { string_scenery_phet_keyboardHelpDialog_pressButtons_StringProperty } from '../../strings/keyboardHelpDialog/pressButtons.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_pressButtonsDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/pressButtonsDescription.js';
import { string_scenery_phet_keyboardHelpDialog_exitADialog_StringProperty } from '../../strings/keyboardHelpDialog/exitADialog.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_exitDialogDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/exitDialogDescription.js';
import { string_scenery_phet_keyboardHelpDialog_setValuesInKeypad_StringProperty } from '../../strings/keyboardHelpDialog/setValuesInKeypad.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_setValuesInKeypadDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/setValuesInKeypadDescription.js';
import { string_scenery_phet_keyboardHelpDialog_toggleCheckboxes_StringProperty } from '../../strings/keyboardHelpDialog/toggleCheckboxes.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_general_toggleCheckboxesDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/general/toggleCheckboxesDescription.js';
import { string_scenery_phet_keyboardHelpDialog_basicActions_StringProperty } from '../../strings/keyboardHelpDialog/basicActions.js';
import '../../../../globals.js';
import optionize from '../../../../phet-core/js/optionize.js';
import ResetAllButton from '../../buttons/ResetAllButton.js';
import sceneryPhet from '../../sceneryPhet.js';
import NumberKeyNode from '../NumberKeyNode.js';
import TextKeyNode from '../TextKeyNode.js';
import KeyboardHelpIconFactory from './KeyboardHelpIconFactory.js';
import KeyboardHelpSection from './KeyboardHelpSection.js';
import KeyboardHelpSectionRow from './KeyboardHelpSectionRow.js';
export default class BasicActionsKeyboardHelpSection extends KeyboardHelpSection {
    constructor(providedOptions) {
        const options = optionize()({
            withCheckboxContent: false,
            withKeypadContent: false
        }, providedOptions);
        // 'Move to next item or group'
        const tabKeyNode = TextKeyNode.tab();
        const moveToNextItemRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_moveToNextItemOrGroup_StringProperty, tabKeyNode, {
            labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_tabGroupDescription_StringProperty
        });
        // 'Move to previous item or group'
        const shiftPlusTabIcon = KeyboardHelpIconFactory.shiftPlusIcon(tabKeyNode);
        const moveToPreviousItemRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_moveToPreviousItemOrGroup_StringProperty, shiftPlusTabIcon, {
            labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_shiftTabGroupDescription_StringProperty
        });
        // 'Move between items in a group'
        const leftRightArrowsIcon = KeyboardHelpIconFactory.leftRightArrowKeysRowIcon();
        const upDownArrowsIcon = KeyboardHelpIconFactory.upDownArrowKeysRowIcon();
        const arrowsIcon = KeyboardHelpIconFactory.iconOrIcon(leftRightArrowsIcon, upDownArrowsIcon);
        const moveBetweenItemsInAGroupRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_moveBetweenItemsInAGroup_StringProperty, arrowsIcon, {
            labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_groupNavigationDescription_StringProperty
        });
        // 'Press buttons'
        const spaceKeyNode = TextKeyNode.space();
        const enterKeyNode = TextKeyNode.enter();
        const spaceOrEnterIcon = KeyboardHelpIconFactory.iconOrIcon(spaceKeyNode, enterKeyNode);
        const pressButtonsItemRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_pressButtons_StringProperty, spaceOrEnterIcon, {
            labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_pressButtonsDescription_StringProperty
        });
        // 'Reset All'
        const resetAllRow = KeyboardHelpSectionRow.fromHotkeyData(ResetAllButton.RESET_ALL_HOTKEY_DATA);
        // 'Exit a dialog'
        const escapeKeyNode = TextKeyNode.esc();
        const exitADialogRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_exitADialog_StringProperty, escapeKeyNode, {
            labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_exitDialogDescription_StringProperty
        });
        const content = [
            moveToNextItemRow,
            moveToPreviousItemRow,
            moveBetweenItemsInAGroupRow
        ];
        if (options.withKeypadContent) {
            // 'Set values within keypad'
            const zeroToNineIcon = KeyboardHelpIconFactory.iconToIcon(new NumberKeyNode(0), new NumberKeyNode(9));
            const setValuesInKeypadRow = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_setValuesInKeypad_StringProperty, zeroToNineIcon, {
                labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_setValuesInKeypadDescription_StringProperty
            });
            content.push(setValuesInKeypadRow);
        }
        // 'Toggle checkboxes'
        if (options.withCheckboxContent) {
            const checkboxSpaceKeyNode = TextKeyNode.space();
            const toggleCheckboxes = KeyboardHelpSectionRow.labelWithIcon(string_scenery_phet_keyboardHelpDialog_toggleCheckboxes_StringProperty, checkboxSpaceKeyNode, {
                labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_general_toggleCheckboxesDescription_StringProperty
            });
            content.push(toggleCheckboxes);
        }
        // a bit strange, but important for ordering with optional rows
        content.push(...[
            pressButtonsItemRow,
            resetAllRow,
            exitADialogRow
        ]);
        // order the rows of content
        super(string_scenery_phet_keyboardHelpDialog_basicActions_StringProperty, content, options);
    }
}
sceneryPhet.register('BasicActionsKeyboardHelpSection', BasicActionsKeyboardHelpSection);
